function r(n){if(n==null||n==="")return null;const t=Number(n);return Number.isFinite(t)?t:null}const u=n=>t=>{const i=r(t);return i===null?"":i.toLocaleString("zh-CN",{minimumFractionDigits:n,maximumFractionDigits:n})},e=u(2),o=u(4),c=u(2),s=u(2),f=u(4);function l(n){const t=r(n);return t===null?"":(t*100).toFixed(2)+"%"}function m(n){const t=r(n);return t===null?"":(t>0?"+":"")+t.toFixed(2)}const a={weight:e,price:o,yield:l,pp:m,money:c,qty:s,ton:f};function d(n,t){if(n==="bool")return t?"是":"";const i=a[n];return i?i(t):t??""}function x(n){return n==null||n===""?null:String(Number(n)/100)}function g(n){return n==null||n===""?"":String(+(Number(n)*100).toFixed(6))}export{f as a,c as b,s as c,o as d,l as e,e as f,m as g,d as h,x as i,g as p};
